import{z as A,x as d,o as t,c as p,q as r,j as o,D as e,d as i,s as n,S as s,b as E}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"MIMO 与速率自适应","description":"","frontmatter":{"title":"MIMO 与速率自适应","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/mimo-rate-adaptation.md","filePath":"cs/mimo-rate-adaptation.md","lastUpdated":1791413859000}'),m={name:"cs/mimo-rate-adaptation.md"};function B(M,a,S,C,h,D){const l=d("Mermaid");return t(),p("div",null,[a[2]||(a[2]=r('<h1 id="mimo-与速率自适应" tabindex="-1">MIMO 与速率自适应 <a class="header-anchor" href="#mimo-与速率自适应" aria-label="Permalink to &quot;MIMO 与速率自适应&quot;">​</a></h1><div class="epigraph"><p>多天线把空间当新的自由度：流数受秩限制；速率自适应则按瞬时 SNR 选 MCS，使工作点跟着衰落走。</p><footer>—— 据 Telatar, Capacity of Multi-antenna Channels, ETT 1999；IEEE 802.11n/ac 整理</footer></div><p><a href="/cs/wifi-frames-ofdm">上一课</a>给出 OFDM 与 MCS 阶梯。缺口是<strong>空间复用与怎么爬阶梯</strong>：MIMO 把 \\(C\\) 近似写成 \\(\\sum\\log(1+\\lambda_i\\mathrm{SNR})\\)；自适应用探测与统计选调制编码。本课不把 Wi‑Fi 6 的 RU 调度写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>单天线 OFDM 已用尽该 \\(B\\) 下的频率自由度。多天线：信道矩阵 \\(H\\) 的奇异值给出并行流。11n 起数据口走空时编码或 SDM。自适应：若固定 64-QAM，深衰落就爆错；降到 QPSK 保住连通。探帧、块确认统计、或闭环 CSI（11ac/ax 更重）驱动降阶/升阶。有线自协商几乎一次定终身；无线每毫秒都可能改 MCS。</p><p><span class="marginnote">术语翻译：MCS（调制与编码方案）就是「每个符号塞多少比特 + 配多强纠错」的档位组合——像变速自行车的变速器：信号好挂高速档（64-QAM，塞得多），信号差挂低速档（QPSK，塞得少但抗噪）；速率自适应就是自动换挡。</span></p><p>不要把天线数写成容量线性倍数：相关与秩不足时流数上不去。</p><p><span class="marginnote">Telatar 与 Foschini 给出高斯 MIMO 容量。802.11 实现是离散 MCS 表。本课不推注水功率分配全文。</span></p><h3 id="天线数不是容量倍数" tabindex="-1">天线数不是容量倍数 <a class="header-anchor" href="#天线数不是容量倍数" aria-label="Permalink to &quot;天线数不是容量倍数&quot;">​</a></h3><p>秩不足则流数上不去。有线自协商几乎一次定终身；无线 MCS 持续跟踪。碰撞会被误读成差信道。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照：开环（STBC 稳）vs 闭环（波束、预编码）。画：估计 \\(H\\) → 选流数与 MCS → 发 → 看 PER → 调。有线 PAM-4 降阶是同类，只是时间尺度不同。</p>',12)),(t(),o(s,null,{default:e(()=>[n(l,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20H%5B%22%E4%BF%A1%E9%81%93%E7%9F%A9%E9%98%B5%20H%22%5D%20--%3E%20RANK%5B%22%E5%8F%AF%E7%94%A8%E6%B5%81%E6%95%B0%22%5D%0A%20%20RANK%20--%3E%20MCS%5B%22%E9%80%89%E8%B0%83%E5%88%B6%E7%BC%96%E7%A0%81%22%5D%0A%20%20MCS%20--%3E%20PER%5B%22%E5%9D%97%E7%A1%AE%E8%AE%A4%2F%E8%AF%AF%E5%8C%85%22%5D%0A%20%20PER%20--%3E%20MCS%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[i("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"AP 与客户端能力取交，类似自协商，但之后仍自适应。LACP 哈希与 MIMO 流无关：流在 PHY，哈希在桥。PFC 很少用在无线跳上。容量仍是上界；MCS 是带 PER 约束的离散点。",-1)),a[5]||(a[5]=E("p",null,[E("span",{class:"marginnote"},"数字实例：容量公式 \\(C=\\sum_i \\log_2(1+\\lambda_i\\,\\mathrm{SNR})\\) 是对数增长：单流 SNR \\(=15\\) 时 \\(C=\\log_2 16=4\\) bit/s/Hz，把功率翻倍到 \\(31\\) 也只到 \\(\\log_2 32=5\\)——功率线性往上堆，速率只按 log 蠕动，这正是降阶「以小带宽损失换大可靠性」的数学背景。")],-1)),a[6]||(a[6]=E("p",null,"隐终端与自适应叠加：碰撞被当成「信道差」会误降速，协议用 RTS/CTS 或调度减轻。",-1)),a[7]||(a[7]=E("p",null,[E("span",{class:"marginnote"},"常见误区：以为丢包都是信号差。碰撞（邻居同时在发）同样让 ACK 不来；速率自适应若把它当深衰落而降档，信道明明空着却用低速慢磨。所以要有 RTS/CTS 或调度，把「碰撞」从「信道差」里摘出来再换挡。")],-1)),(t(),o(s,null,{default:e(()=>[n(l,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20TX%5B%22%E5%8F%91%E5%87%BA%E4%B8%80%E5%8C%85%22%5D%20--%3E%20LOSS%7B%22%E6%94%B6%E5%88%B0%20ACK%20%E5%90%97%3F%22%7D%0A%20%20LOSS%20--%3E%7C%22%E4%B8%A2%E4%BA%86%22%7C%20WHY%7B%22%E6%98%AF%E4%BF%A1%E9%81%93%E5%B7%AE%E8%BF%98%E6%98%AF%E7%A2%B0%E6%92%9E%3F%22%7D%0A%20%20WHY%20--%3E%7C%22%E6%B7%B1%E8%A1%B0%E8%90%BD%22%7C%20DOWN%5B%22%E9%99%8D%20MCS%20%E6%8D%A2%E6%8A%97%E5%99%AA%E6%A1%A3%22%5D%0A%20%20WHY%20--%3E%7C%22%E7%A2%B0%E6%92%9E%22%7C%20MISTAKE%5B%22%E8%AF%AF%E9%99%8D%E9%80%9F%3A%20%E7%A9%BA%E4%BF%A1%E9%81%93%E6%85%A2%E6%85%A2%E7%A3%A8%22%5D%0A%20%20MISTAKE%20--%3E%20FIX%5B%22%E5%85%88%20RTS%2FCTS%20%E6%88%96%E8%B0%83%E5%BA%A6%E6%B6%88%E7%A2%B0%E6%92%9E%22%5D%0A%20%20DOWN%20--%3E%20OK%5B%22PER%20%E5%9B%9E%E5%88%B0%E7%9B%AE%E6%A0%87%E5%86%8D%E9%80%90%E6%AD%A5%E5%8D%87%E9%98%B6%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=r('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 MU-MIMO 用户选择算法的全部。Wi‑Fi 6 OFDMA 是下一课。后课默认：MIMO 给空间自由度；自适应跟踪衰落。</p><p>不要把「8×8」广告当室内总能 8 流。</p><p>下一课<a href="/cs/wifi6-ofdma">WiFi 6 / 7 与 OFDMA</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>MIMO 容量由信道秩与奇异值决定。</li><li>MCS 自适应是离散逼近瞬时 \\(C\\)。</li><li>碰撞会污染速率估计。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：Telatar, 1999；IEEE 802.11n/ac。</li></ul>',6))])}const T=A(m,[["render",B]]);export{u as __pageData,T as default};
